// Value: protects=the orders filter controls follow the URL: its own late-arriving write never undoes a newer choice, and a URL the page did not write (Back, a link) drops the pending choices so the next write builds on the new props;
// fails_when=the written/syncedQuery reconcile in FinanceOrdersPage is removed or simplified (always clear, or never clear): an older write landing resets the newer Đợt choice, or after Back the stale source=sb and month stay in the controls and are re-sent with the next change;
// why_new=finance-orders-page.test.tsx mocks one fixed URL, so the query-change branch never runs; the preview test only reads the initial URL;
// seam=none (next/navigation is mocked with a settable search string and a recording router.replace, the payment-request presentation test pattern); no_claim=the real Next router timing and the server page re-running the RPC (props are re-rendered by hand)
import { cleanup, fireEvent, render, screen } from "@testing-library/react";
import { afterEach, describe, expect, it, vi } from "vitest";

import { FinanceOrdersPage } from "@/features/finance/components/finance-orders-page";
import type { FinanceOrderFiltersState, FinanceOrdersDashboardReadModel } from "@/features/finance/read-models";

const router = vi.hoisted(() => ({ replace: vi.fn() }));
const search = vi.hoisted(() => ({ value: "month=2026-08" }));

vi.mock("next/navigation", () => ({
  useRouter: () => router,
  useSearchParams: () => new URLSearchParams(search.value),
}));
vi.mock("@/features/finance/actions/finance-actions", () => ({ setFinanceOrderReviewAction: vi.fn() }));

afterEach(() => {
  cleanup();
  vi.clearAllMocks();
  search.value = "month=2026-08";
});

const dashboard: FinanceOrdersDashboardReadModel = {
  month: "2026-08-01",
  orders: [{
    bankTransactionId: "SEPAY-100",
    checkedAt: null,
    checkedBy: null,
    classCode: "7A",
    className: "Toán 7A",
    guardianFullName: "Nguyễn Thị Mai",
    guardianPhone: "0900000000",
    isChecked: false,
    leadSourceCode: "sandbox_partner",
    leadSourceName: "Đối tác Sandbox",
    mechanismCode: "renewal_sb_20_percent",
    operatingCostStatus: "configured",
    operatingCostVnd: 560_000,
    orderType: "renewal",
    referenceCode: "PAY-100",
    saleOwnerFullName: "Trần Hải",
    saleOwnerId: "sale-1",
    sepayTransactionId: "transaction-1",
    settlementPeriod: 2,
    sourceCashflowRecordId: "cashflow-1",
    sourceCode: "sb",
    sourceLabel: "SB",
    studentFullName: "Nguyễn Minh An",
    studentId: "student-1",
    studentPublicCode: "HV001",
    transactionAt: "2026-08-15T03:00:00.000Z",
    transferContent: "TTVC PAY-100",
    tuitionAmountVnd: 2_800_000,
  }],
  settlement: [],
  settlementEligible: true,
  summary: { checkedCount: 0, operatingCostVnd: 560_000, orderCount: 1, tuitionAmountVnd: 2_800_000, uncheckedCount: 1, unconfiguredCount: 0 },
};

const filters = (overrides: Partial<FinanceOrderFiltersState> = {}): FinanceOrderFiltersState => ({
  month: "2026-08",
  orderType: "",
  period: "",
  source: "",
  ...overrides,
});

describe("Finance Orders filters follow the URL (step 14c)", () => {
  it("keeps a newer choice when its own older write lands late", () => {
    const { rerender } = render(<FinanceOrdersPage canReview={false} dashboard={dashboard} filters={filters()} />);

    fireEvent.change(screen.getByLabelText("Nguồn"), { target: { value: "sb" } });
    fireEvent.change(screen.getByLabelText("Đợt quyết toán"), { target: { value: "2" } });
    expect(router.replace).toHaveBeenLastCalledWith("/finance/orders?month=2026-08&source=sb&period=2", { scroll: false });

    // Next applies the first write late; the server page answers it with source=sb only.
    search.value = "month=2026-08&source=sb";
    rerender(<FinanceOrdersPage canReview={false} dashboard={dashboard} filters={filters({ source: "sb" })} />);
    expect(screen.getByLabelText("Đợt quyết toán")).toHaveValue("2");
    expect(screen.getByLabelText("Nguồn")).toHaveValue("sb");

    // A third change still builds on the newest choices, not on the stale props.
    fireEvent.change(screen.getByLabelText("Loại đơn"), { target: { value: "renewal" } });
    expect(router.replace).toHaveBeenLastCalledWith(
      "/finance/orders?month=2026-08&orderType=renewal&source=sb&period=2",
      { scroll: false },
    );
  });

  it("lets a URL it did not write win and builds the next write on the new props", () => {
    const { rerender } = render(<FinanceOrdersPage canReview={false} dashboard={dashboard} filters={filters()} />);

    fireEvent.change(screen.getByLabelText("Nguồn"), { target: { value: "sb" } });
    expect(screen.getByLabelText("Nguồn")).toHaveValue("sb");

    // Back (or an outside link) to July before the write landed.
    search.value = "month=2026-07";
    rerender(<FinanceOrdersPage canReview={false} dashboard={dashboard} filters={filters({ month: "2026-07" })} />);
    expect(screen.getByLabelText("Nguồn")).toHaveValue("");
    expect(screen.getByLabelText("Tháng giao dịch")).toHaveValue("2026-07");

    fireEvent.change(screen.getByLabelText("Loại đơn"), { target: { value: "renewal" } });
    expect(router.replace).toHaveBeenLastCalledWith("/finance/orders?month=2026-07&orderType=renewal", { scroll: false });
  });

  it("clears each landed write, so returning to an earlier URL shows that URL's filters", () => {
    const { rerender } = render(<FinanceOrdersPage canReview={false} dashboard={dashboard} filters={filters()} />);

    fireEvent.change(screen.getByLabelText("Nguồn"), { target: { value: "sb" } });
    search.value = "month=2026-08&source=sb";
    rerender(<FinanceOrdersPage canReview={false} dashboard={dashboard} filters={filters({ source: "sb" })} />);

    fireEvent.change(screen.getByLabelText("Đợt quyết toán"), { target: { value: "2" } });
    expect(router.replace).toHaveBeenLastCalledWith("/finance/orders?month=2026-08&source=sb&period=2", { scroll: false });
    search.value = "month=2026-08&source=sb&period=2";
    rerender(<FinanceOrdersPage canReview={false} dashboard={dashboard} filters={filters({ period: "2", source: "sb" })} />);
    expect(screen.getByLabelText("Đợt quyết toán")).toHaveValue("2");

    // Back to the source-only URL this page wrote earlier: it already landed, so it is not a pending write.
    search.value = "month=2026-08&source=sb";
    rerender(<FinanceOrdersPage canReview={false} dashboard={dashboard} filters={filters({ source: "sb" })} />);
    expect(screen.getByLabelText("Đợt quyết toán")).toHaveValue("");
    expect(screen.getByLabelText("Nguồn")).toHaveValue("sb");
  });
});
